import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 47 Too high a price?","description":"学习 because、therefore 与因果关系，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 47 Too high a price?","description":"学习 because、therefore 与因果关系，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 because、therefore 与因果关系，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 46 Do it yourself","link":"/life/english/new-concept/book-3/unit-03/lesson-046"},"next":{"text":"第三册：培养技能 · Lesson 48 The silent village","link":"/life/english/new-concept/book-3/unit-03/lesson-048"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 46 Do it yourself","link":"/life/english/new-concept/book-3/unit-03/lesson-046"},"next":{"text":"第三册：培养技能 · Lesson 48 The silent village","link":"/life/english/new-concept/book-3/unit-03/lesson-048"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-047.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-047.md"}'),r={name:"life/english/new-concept/book-3/unit-03/lesson-047.md"};function i(s,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-47-too-high-a-price" tabindex="-1">第三册：培养技能 · Lesson 47 Too high a price? <a class="header-anchor" href="#第三册-培养技能-·-lesson-47-too-high-a-price" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 47 Too high a price?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕噪声与生活质量的代价学习提出有证据的论点。评价一种便利时，也要交代它对睡眠、交流或环境的影响，不用夸张词代替观察。学习因果连接词和结果副词的标点差别，将原因、结果和个人建议组成一段可追踪的论证。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>noise</td><td>/nɔɪz/</td><td>n.</td><td>噪声</td><td>persistent noise</td></tr><tr><td>disturb</td><td>/dɪˈstɜːb/</td><td>v.</td><td>打扰</td><td>disturb sleep</td></tr><tr><td>consequence</td><td>/ˈkɒnsɪkwəns/</td><td>n.</td><td>后果</td><td>an unintended consequence</td></tr><tr><td>benefit</td><td>/ˈbenɪfɪt/</td><td>n.</td><td>益处</td><td>a practical benefit</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>at the expense of — 以牺牲某方面为代价</li><li>contribute to — 促成某结果，通常不表示唯一原因</li></ul><h2 id="语法讲解-because、therefore-与因果关系" tabindex="-1">语法讲解：because、therefore 与因果关系 <a class="header-anchor" href="#语法讲解-because、therefore-与因果关系" aria-label="Permalink to &quot;语法讲解：because、therefore 与因果关系&quot;">​</a></h2><p>because 引导原因从句，能与主句构成一个复合句；therefore 是连接性副词，通常需要句号、分号或与连词配合来连接独立分句，不能仅用一个逗号代替句法连接。because of 后接名词性成分，不能直接接完整分句。语法上的因果标记也需要证据支持，两个现象先后发生不自动构成因果。讨论公共问题时可使用 may contribute to 限定影响，避免把复杂结果归因于单一因素或把个人感受说成普遍事实。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The courtyard remained noisy after midnight; therefore, several residents moved their bedrooms to the rear.</p></blockquote><p>午夜后庭院仍很嘈杂，因此几位住户把卧室改设在后侧。</p><p>分号分开完整分句，therefore 标明结果；several 限定受影响者，未概括为所有住户。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Because of the traffic was loud 错把完整句接在介词后；可写 Because the traffic was loud 或 Because of the loud traffic。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 however 和 therefore 时先停顿，再读后面的主要信息；回听能否判断哪里是转折、哪里是因果。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The new delivery entrance saves workers time. However, metal carts wake nearby residents before dawn. Rubber wheels and later collection hours may reduce the disturbance.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句评价一个虚构便利设施的代价，列出观察和改进建议。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>便利与代价均具体，may 避免对改进效果作未经测试的保证。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句 therefore 前为何不用普通逗号直接拼接？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 两侧都是完整分句。</p><p><strong>解析：</strong> 连接副词本身不能充当并列连词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：The event stopped because ___ the rain.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> of</p><p><strong>解析：</strong> because of 接名词 rain。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>contribute to 是否必然表示唯一原因？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> 通常只表示起促成作用。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：because、therefore 与因果关系。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-046">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-048">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(r,[["render",i]]);export{p as __pageData,b as default};
